const crypto = require('crypto');
const LOOKBACK_MS = 24 * 60 * 60 * 1000;
const cutoff = Date.now() - LOOKBACK_MS;

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedSheetRows) staticData.processedSheetRows = {};

function parseSheetDate(value) {
  if (value == null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) {
    return new Date((value - 25569) * 86400000);
  }
  const s = String(value).trim();
  if (!s) return null;
  let d = new Date(s);
  if (!Number.isNaN(d.getTime())) return d;
  const m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) {
    const day = +m[1];
    const mon = +m[2];
    let yr = +m[3];
    if (yr < 100) yr += 2000;
    d = new Date(yr, mon - 1, day, +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
    if (!Number.isNaN(d.getTime())) return d;
  }
  return null;
}

function normalizeSpainPhone(raw) {
  if (raw == null || String(raw).trim() === '') {
    return { valid: false, reason: 'empty' };
  }
  let d = String(raw).replace(/\D/g, '');
  if (d.startsWith('0034')) d = d.slice(2);
  if (d.length === 9 && /^[6789]/.test(d)) d = '34' + d;
  if (d.length === 11 && d.startsWith('34')) {
    const national = d.slice(2);
    if (/^[6789]\d{8}$/.test(national)) {
      return { valid: true, phone_digits: d };
    }
  }
  return { valid: false, reason: 'invalid_spain' };
}

function rowKey(j) {
  const tab = j.sheet_tab || 'unknown';
  const rn = j.row_number ?? j.rowNumber ?? '';
  const fecha = j.Fecha ?? '';
  const tel = j.telefono ?? '';
  return `${tab}:${rn}:${fecha}:${tel}`;
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const key = rowKey(j);
  if (staticData.processedSheetRows[key]) continue;

  const fe = parseSheetDate(j.Fecha);
  if (!fe || fe.getTime() < cutoff) continue;

  const norm = normalizeSpainPhone(j.telefono);
  if (!norm.valid) continue;

  const phone_digits = norm.phone_digits;
  out.push({
    json: {
      sheet_tab: j.sheet_tab,
      sheet_row_key: key,
      phone_digits,
      phone_hash: crypto.createHash('sha256').update(phone_digits, 'utf8').digest('hex'),
      source: String(j.source || j.sheet_tab || 'sheets').slice(0, 120),
      sheet_fecha: fe.toISOString(),
      first_seen_at: fe.toISOString(),
      telefono_raw: j.telefono,
      row_number: j.row_number ?? j.rowNumber,
    },
  });
}

return out;

const staticData = $getWorkflowStaticData('global');
if (!staticData.phones) staticData.phones = {};
if (!staticData.duplicateEvents) staticData.duplicateEvents = [];
if (!staticData.processedSheetRows) staticData.processedSheetRows = {};

const prep = $input.first().json;
const phone = prep.phone_digits;
const now = new Date().toISOString();

let result;
if (staticData.phones[phone]) {
  const ex = staticData.phones[phone];
  staticData.duplicateEvents.push({
    event_key: `dup_${phone}_${now}`,
    phone_digits: phone,
    received_at: now,
    source: prep.source,
    first_source: ex.first_source,
    first_seen_at: ex.first_seen_at,
    action: 'duplicate_not_processed',
  });
  result = {
    ok: true,
    recorded: true,
    is_duplicate: true,
    phone_digits: phone,
    source: prep.source,
    first_source: ex.first_source,
    phone_hash: ex.phone_hash || prep.phone_hash,
    claimed_at: ex.claimed_at,
    first_seen_at: ex.first_seen_at,
    sheet_tab: prep.sheet_tab,
    sheet_row_key: prep.sheet_row_key,
  };
} else {
  staticData.phones[phone] = {
    phone_digits: phone,
    phone_hash: prep.phone_hash,
    first_source: prep.source,
    first_seen_at: prep.first_seen_at || prep.sheet_fecha || now,
    claimed_at: now,
    meta_synced_at: '',
  };
  result = {
    ok: true,
    recorded: true,
    is_duplicate: false,
    phone_digits: phone,
    phone_hash: prep.phone_hash,
    source: prep.source,
    claimed_at: now,
    first_seen_at: prep.first_seen_at || prep.sheet_fecha || now,
    first_source: prep.source,
    sheet_tab: prep.sheet_tab,
    sheet_row_key: prep.sheet_row_key,
  };
}

if (prep.sheet_row_key) {
  staticData.processedSheetRows[prep.sheet_row_key] = now;
}

return [{ json: result }];

const r = $input.first().json;
const receivedAt = new Date().toISOString();
return [{
  json: {
    ...r,
    duplicate_tag: 'new',
    is_duplicate: 'no',
    received_at: receivedAt,
    first_source: r.first_source || r.source || '',
    first_seen_at: r.first_seen_at || r.claimed_at || receivedAt,
    phone_hash: r.phone_hash || '',
  },
}];
